const stripe=process.env.STRIPE_SECRET_KEY?new Stripe(process.env.STRIPE_SECRET_KEY):null;
app.disable('x-powered-by');app.use(helmet({contentSecurityPolicy:false}));
app.post('/api/stripe/webhook',express.raw({type:'application/json'}),(req,res)=>{
 if(!stripe||!process.env.STRIPE_WEBHOOK_SECRET)return res.status(503).send('not configured');
 let event;try{event=stripe.webhooks.constructEvent(req.body,req.headers['stripe-signature'],process.env.STRIPE_WEBHOOK_SECRET)}catch{return res.status(400).send('invalid signature')}
 if(db.prepare('SELECT 1 FROM processed_stripe_events WHERE event_id=?').get(event.id))return res.json({received:true});
 const obj=event.data.object;try{
 if(['customer.subscription.created','customer.subscription.updated','customer.subscription.deleted'].includes(event.type)){
 const plan=Object.entries({light:process.env.STRIPE_PRICE_LIGHT,standard:process.env.STRIPE_PRICE_STANDARD,premium:process.env.STRIPE_PRICE_PREMIUM}).find(([,p])=>p&&obj.items?.data?.some(x=>x.price?.id===p))?.[0]||'trial';
 db.prepare('UPDATE users SET plan=?,subscription_status=? WHERE stripe_customer=?').run(plan,obj.status,obj.customer);
 }
 db.prepare('INSERT INTO processed_stripe_events(event_id) VALUES(?)').run(event.id);res.json({received:true});
 }catch{res.status(500).send('processing failed')}
});
