const fail=(res,code,msg)=>res.status(code).json({error:msg});
const token=user=>jwt.sign({uid:user.id},secret,{expiresIn:'7d'});
const requireAuth=(req,res,next)=>{if(secret.length<32)return fail(res,503,'JWT_SECRET not configured');try{const t=req.cookies.session;req.user=jwt.verify(t,secret);next()}catch{return fail(res,401,'ログインしてください')}};
const authSchema=z.object({email:z.string().email().max(200),password:z.string().min(10).max(100)});
app.post('/api/register',(req,res)=>{const v=authSchema.safeParse(req.body);if(!v.success)return fail(res,400,'メールと10文字以上のパスワードが必要');if(secret.length<32)return fail(res,503,'JWT_SECRET not configured');const id=crypto.randomUUID();try{db.prepare('INSERT INTO users(id,email,password_hash) VALUES(?,?,?)').run(id,v.data.email.toLowerCase(),bcrypt.hashSync(v.data.password,12))}catch{return fail(res,409,'登録できません（登録済みの可能性）')}res.cookie('session',token({id}),{httpOnly:true,secure:ORIGIN.startsWith('https:'),sameSite:'lax',maxAge:604800000});res.json({ok:true})});
app.post('/api/login',(req,res)=>{const v=authSchema.safeParse(req.body);if(!v.success)return fail(res,400,'入力を確認してください');const u=db.prepare('SELECT * FROM users WHERE email=?').get(v.data.email.toLowerCase());if(!u||!bcrypt.compareSync(v.data.password,u.password_hash))return fail(res,401,'認証できません');if(secret.length<32)return fail(res,503,'JWT_SECRET not configured');res.cookie('session',token(u),{httpOnly:true,secure:ORIGIN.startsWith('https:'),sameSite:'lax',maxAge:604800000});res.json({ok:true})});
app.post('/api/logout',(_req,res)=>{res.clearCookie('session');res.json({ok:true})});
const month=()=>new Date().toISOString().slice(0,7);
const limits={light:10,standard:50,premium:150};
const planUsage=id=>db.prepare('SELECT count FROM usage_monthly WHERE user_id=? AND month=?').get(id,month())?.count||0;
const me=id=>{const u=db.prepare('SELECT id,email,plan,trial_left,subscription_status FROM users WHERE id=?').get(id);if(!u)return null;return {...u,monthlyUsed:planUsage(id),monthlyLimit:limits[u.plan]||0}};

