// v1.4 independent JRA research QA: authenticated and explicitly non-commercial.
db.exec(`CREATE TABLE IF NOT EXISTS jra_research_v14 (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_jra_research_v14_user ON jra_research_v14(user_id,kind,created_at);`);
const researchBody=z.object({kind:z.enum(['snapshot','darkhorse-evaluation','model-review']),data:z.record(z.any())});
app.post('/api/jra/v14/audit',requireAuth,(req,res)=>{const v= z.object({date:z.string(),venue:z.string(),race:z.number(),surface:z.string(),distance:z.number(),horses:z.array(z.object({number:z.number(),name:z.string()})),source:z.object({name:z.string(),observedAt:z.string()}).optional()}).safeParse(req.body);if(!v.success)return fail(res,400,'監査用入力形式が不正です');return res.json(validateJraRace(v.data))});
app.post('/api/jra/v14/research',requireAuth,(req,res)=>{const p=researchBody.safeParse(req.body);if(!p.success)return fail(res,400,'研究記録の形式が不正です');const v=p.data;let result;
if(v.kind==='snapshot')result=freezeResearchSnapshot(v.data);
if(v.kind==='darkhorse-evaluation'){if(!Array.isArray(v.data.records)||v.data.records.length>500)return fail(res,400,'最大500レース');result=evaluateDarkHorseAtK(v.data.records,3,10)}
if(v.kind==='model-review')result=assessModelRevision(v.data.baseline,v.data.candidate);
const id=crypto.randomUUID();db.prepare('INSERT INTO jra_research_v14(id,user_id,kind,payload) VALUES(?,?,?,?)').run(id,req.user.uid,v.kind,JSON.stringify({input:v.data,result}));return res.json({id,kind:v.kind,result,productionGate:'HOLD'})});
app.get('/api/jra/v14/research',requireAuth,(req,res)=>res.json({records:db.prepare('SELECT id,kind,payload,created_at FROM jra_research_v14 WHERE user_id=? ORDER BY created_at DESC LIMIT 50').all(req.user.uid).map(x=>({...x,payload:JSON.parse(x.payload)})),officialResultsConnected:false}));
app.post('/api/jra/v14/verify',requireAuth,(req,res)=>{const v=z.object({digest:z.string(),canonical:z.string()}).safeParse(req.body);if(!v.success)return fail(res,400,'ハッシュデータ不正');res.json({matches:verifyResearchSnapshot(v.data),notIndependentTimestamp:true})});

// Data provider intentionally NOT fabricated: authorized adapter must be implemented before auto ingestion works.
app.get('/api/race/:key',requireAuth,(req,res)=>{const cache=db.prepare('SELECT * FROM provider_cache WHERE race_key=?').get(req.params.key);if(!cache)return fail(res,424,'契約済み競馬データ提供元は未接続です。出走表の自動取得は利用できません');res.json(JSON.parse(cache.data_json))});
const horse=z.object({number:z.number().int().positive(),name:z.string().min(1),odds:z.number().positive().optional(),form:z.string().max(1000).optional(),style:z.string().max(50).optional(),workout:z.string().max(500).optional(),paddock:z.string().max(500).optional(),notes:z.string().max(1000).optional(),paceScore:z.number().min(0).max(100).optional(),conditionScore:z.number().min(0).max(100).optional(),classFitScore:z.number().min(0).max(100).optional(),workoutScore:z.number().min(0).max(100).optional(),troubleRecoveryScore:z.number().min(0).max(100).optional()});
const JRA_VENUES=new Set(['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉']);
const isJraVenue=v=>JRA_VENUES.has(String(v||'').trim().replace(/競馬場$/,''));
const predSchema=z.object({date:z.string().max(30),venue:z.string().min(1).max(100),race:z.string().max(20),surface:z.string().max(30).default('unknown'),distance:z.number().int().min(0).max(5000).default(0),ground:z.string().max(30).default('unknown'),ticket:z.enum(['trifecta','trio','quinella','wide','win']).default('trifecta'),budget:z.number().int().min(100).max(1000000),maxPoints:z.number().int().min(1).max(500),favHorse:z.string().max(100).optional(),horses:z.array(horse).min(2).max(24),dataVerified:z.boolean().default(false),withdrawalsVerified:z.boolean().default(false),oddsVerified:z.boolean().default(false),weightVerified:z.boolean().default(false),simulationsActuallyComputed:z.boolean().default(false),trackBiasVerified:z.boolean().default(false)});
const SYSTEM=`あなたはAOZORA RACING AIの予想分析補助エンジン。実際の予想精度、的中、利益を保証しない。入力の出典にない馬情報・調教・馬体・パドック・オッズ・予想確率・計算実施を捏造しない。全頭評価、脚質隊列、展開3分岐、A評価、X評価、穴馬、各馬の1/2/3着筋、推奨馬独立監査、根拠と反証を日本語で丁寧に出す。対象はJRA中央競馬のみ。地方競馬専用ルールは適用しない。中央競馬用の評価と反証、2着独立評価、3着穴馬保護を検証する。買い目はユーザーの券種・点数・予算を尊重する。条件が整わなければ参考候補は表示するが購入ゲートは必ず見送り。未実施のシミュレーション回数を絶対に名乗らない。厳格な購入ゲートはサーバー判定に従う。JSONのみで keys summary,marks(array of {number,name,mark,reason}),paceScenarios(array),darkHorses(array),favHorseReview(object),ticketCandidates(array of strings),risks(array),dataGaps(array),recommendationReason を出力。`;
function gate(v){const misses=[];if(!v.dataVerified)misses.push('出走表・成績データ未検証');if(!v.withdrawalsVerified)misses.push('取消確認なし');if(!v.oddsVerified)misses.push('実オッズ未確認');if(!v.weightVerified)misses.push('馬体重確認なし');if(!v.trackBiasVerified)misses.push('当日馬場傾向未確認');misses.push('サーバーで検証されたシミュレーション証跡なし（参考予想のみ）');if(v.horses.length<5)misses.push('全頭監査データ不足の可能性');return {status:misses.length?'HOLD':'REVIEW_REQUIRED',misses};}
app.post('/api/predict',requireAuth,rateLimit({windowMs:3600000,limit:30}),async(req,res)=>{const parsed=predSchema.safeParse(req.body);if(!parsed.success)return fail(res,400,'入力データを確認してください');const v=parsed.data;if(!isJraVenue(v.venue))return fail(res,400,'JRA中央競馬10場のみ対応');const u=me(req.user.uid);const active=['light','standard','premium'].includes(u.plan)&&['active','trialing'].includes(u.subscription_status);if(active&&u.monthlyUsed>=u.monthlyLimit)return fail(res,429,'月間予想回数の上限に達しました');if(!active&&u.trial_left<=0)return fail(res,402,'無料3回を使い切りました。');if(!process.env.OPENAI_API_KEY)return fail(res,503,'OPENAI_API_KEY未設定：AI分析はまだ使用できません');const g=gate(v);
 const seed=Number.parseInt(crypto.createHash('sha256').update(JSON.stringify({date:v.date,venue:v.venue,race:v.race,horses:v.horses})).digest('hex').slice(0,8),16);
 const simulation=simulate(v.horses,2000,seed);
 const tickets=generateTickets(simulation,v.ticket,v.maxPoints,v.budget);
 try{const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),45000);let response;try{response=await fetch('https://api.openai.com/v1/chat/completions',{method:'POST',headers:{Authorization:`Bearer ${process.env.OPENAI_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({model:process.env.OPENAI_MODEL||'gpt-4.1-mini',temperature:0.2,response_format:{type:'json_object'},messages:[{role:'system',content:SYSTEM},{role:'user',content:JSON.stringify({race:v,gate:g,important:'未検証データは未確認と明記。購入許可は出さない。'})}]}),signal:controller.signal})}finally{clearTimeout(timer)}if(!response.ok)throw Error('AI upstream '+response.status);const raw=await response.json();const result=JSON.parse(raw.choices[0].message.content);
 result.simulation={method:simulation.method,runs:simulation.runs,seed:simulation.seed,calibrated:false,counts:simulation.counts,limitations:'未校正のオッズ加重抽選。脚質・展開・馬場の実証的再現ではない'};
 result.generatedTickets=tickets;
 result.uniqueFeatures=experimentalSuite(v); result.uniqueFeatures.learning=undefined; result.uniqueFeatures.stopper.status='HOLD';
 const id=crypto.randomUUID();db.prepare('INSERT INTO predictions(id,user_id,race_key,request_json,result_json,gate) VALUES(?,?,?,?,?,?)').run(id,u.id,`${v.date}:${v.venue}:${v.race}`,JSON.stringify(v),JSON.stringify(result),g.status);if(!active)db.prepare('UPDATE users SET trial_left=trial_left-1 WHERE id=? AND trial_left>0').run(u.id);else db.prepare('INSERT INTO usage_monthly(user_id,month,count) VALUES(?,?,1) ON CONFLICT(user_id,month) DO UPDATE SET count=count+1').run(u.id,month());res.json({id,result,gate:g,usage:raw.usage,trial_left:me(u.id).trial_left});}catch(e){res.status(502).json({error:'AI解析に失敗しました。試行は消費していません',detail:String(e.message).slice(0,100)})}});
app.post('/api/predictions/:id/outcome',requireAuth,(req,res)=>{
 const body=z.object({finish:z.array(z.number().int().min(1).max(24)).min(3).max(24),sourceNote:z.string().min(3).max(300)}).safeParse(req.body);
 if(!body.success||new Set(body.data.finish).size!==body.data.finish.length)return fail(res,400,'着順・結果確認元を確認してください');
 const rec=db.prepare('SELECT * FROM predictions WHERE id=? AND user_id=?').get(req.params.id,req.user.uid);
 if(!rec)return fail(res,404,'予想がありません');const v=JSON.parse(rec.request_json),r=JSON.parse(rec.result_json);
 if(body.data.finish.some(n=>!v.horses.some(h=>h.number===n)))return fail(res,400,'出走表にない馬番が含まれます');
 db.prepare(`INSERT INTO race_outcomes(id,user_id,prediction_id,finish_json,source_note) VALUES(?,?,?,?,?) ON CONFLICT(user_id,prediction_id) DO UPDATE SET finish_json=excluded.finish_json,source_note=excluded.source_note,created_at=CURRENT_TIMESTAMP`).run(crypto.randomUUID(),req.user.uid,rec.id,JSON.stringify(body.data.finish),body.data.sourceNote);
 const checks=(r.generatedTickets?.candidates||[]).map(x=>({...x,hit:evaluatePrediction(x.selection,body.data.finish,v.ticket)}));res.json({finish:body.data.finish,checks,hitCount:checks.filter(x=>x.hit).length,officiallyVerified:false});
});
// v0.9 source-provenance gate: all new operations are user-scoped.
const v09uuid=z.string().uuid();
function own09(req,res){const p=db.prepare('SELECT id,request_json,result_json,race_key FROM predictions WHERE id=? AND user_id=?').get(req.params.id,req.user.uid);if(!p){fail(res,404,'対象予想が見つかりません');return null}return {...p,request:JSON.parse(p.request_json)}}
function save09(uid,pid,kind,data){const id=crypto.randomUUID();db.prepare('INSERT INTO reverse_v09_records(id,user_id,prediction_id,kind,payload_json) VALUES(?,?,?,?,?)').run(id,uid,pid,kind,JSON.stringify(data));return id}
app.post('/api/v09/:id/reverse',requireAuth,(req,res)=>{if(!v09uuid.safeParse(req.params.id).success)return fail(res,400,'ID不正');const p=own09(req,res);if(!p)return;const v=z.object({pace:z.enum(['normal','slow','fast']).default('normal'),excludeFavorite:z.boolean().default(false),focus:z.string().max(100).default('all')}).safeParse(req.body||{});if(!v.success)return fail(res,400,'設定不正');const analysis=reverseHunter(p.request,v.data),trust=reliabilityAudit(p.request);const id=save09(req.user.uid,p.id,'reverse',{analysis,trust});res.json({recordId:id,analysis,trust,autoFeed:false,modelValidated:false})});
app.post('/api/v09/:id/change',requireAuth,(req,res)=>{const p=own09(req,res);if(!p)return;const v=z.object({before:z.record(z.union([z.string(),z.number(),z.boolean(),z.null()])),after:z.record(z.union([z.string(),z.number(),z.boolean(),z.null()])),source:z.string().min(3).max(250)}).safeParse(req.body);if(!v.success)return fail(res,400,'変更記録不正');const d={...changes(v.data.before,v.data.after),source:v.data.source};const id=save09(req.user.uid,p.id,'changed',d);res.json({recordId:id,...d})});
app.get('/api/v09/:id/records',requireAuth,(req,res)=>{const p=own09(req,res);if(!p)return;res.json(db.prepare('SELECT id,kind,payload_json,created_at FROM reverse_v09_records WHERE user_id=? AND prediction_id=? ORDER BY created_at DESC LIMIT 100').all(req.user.uid,p.id).map(x=>({...x,payload:JSON.parse(x.payload_json),payload_json:undefined})))});
