app.get('/api/v07/:id/seal',requireAuth,(req,res)=>{const p=predictionFor(req.user.uid,req.params.id);if(!p)return fail(res,404,'予想なし');const seal=db.prepare('SELECT * FROM v07_evidence WHERE user_id=? AND prediction_id=?').get(req.user.uid,p.id);if(!seal)return fail(res,404,'未封印');const payload={predictionId:p.id,raceKey:p.race_key,predictionCreatedAt:p.created_at,request:JSON.parse(seal.request_json),result:JSON.parse(seal.result_json)};res.json({hash:seal.snapshot_hash,sealedAt:seal.sealed_at,contentIntact:digest(payload)===seal.snapshot_hash,independentlyTimestamped:false})});
app.post('/api/v07/:id/autopsy',requireAuth,(req,res)=>{const p=predictionFor(req.user.uid,req.params.id);if(!p)return fail(res,404,'予想なし');const body=z.object({predicted:z.array(z.number().int()).max(30),finish:z.array(z.number().int()).min(3).max(30),reasons:z.array(z.string().max(250)).max(10).default([])}).safeParse(req.body);if(!body.success||new Set(body.data.finish).size!==body.data.finish.length)return fail(res,400,'着順が不正');const o=db.prepare('SELECT finish_json FROM race_outcomes WHERE prediction_id=? AND user_id=?').get(p.id,req.user.uid);if(!o)return fail(res,409,'先に結果照合画面で着順を記録してください');if(JSON.stringify(JSON.parse(o.finish_json).slice(0,3))!==JSON.stringify(body.data.finish.slice(0,3)))return fail(res,409,'登録済み結果と一致しません');const report=failureAutopsy(body.data);res.json({...report,record:saveV07(req.user.uid,p.id,'autopsy',{...body.data,report})})});
app.post('/api/v07/:id/human-ai',requireAuth,(req,res)=>{const p=predictionFor(req.user.uid,req.params.id);if(!p)return fail(res,404,'予想なし');const v=z.object({human:z.array(z.number().int().min(1).max(30)).min(1).max(30),ai:z.array(z.number().int().min(1).max(30)).min(1).max(30)}).safeParse(req.body);if(!v.success)return fail(res,400,'馬番リストが不正');const horses=new Set(JSON.parse(p.request_json).horses.map(h=>h.number));if([...v.data.human,...v.data.ai].some(x=>!horses.has(x)))return fail(res,400,'出走表外の馬番');const o=db.prepare('SELECT finish_json FROM race_outcomes WHERE prediction_id=? AND user_id=?').get(p.id,req.user.uid);const comparison=o?humanAICompare({...v.data,finish:JSON.parse(o.finish_json)}):{pendingResult:true,humanOnly:v.data.human.filter(n=>!v.data.ai.includes(n)),aiOnly:v.data.ai.filter(n=>!v.data.human.includes(n))};res.json({comparison,record:saveV07(req.user.uid,p.id,'human-ai',{...v.data,comparison}),outcomeUserEntered:!!o})});
app.get('/api/v07/:id/records',requireAuth,(req,res)=>{if(!predictionFor(req.user.uid,req.params.id))return fail(res,404,'予想なし');const records=db.prepare('SELECT id,kind,payload_json,hash,created_at FROM v07_records WHERE user_id=? AND prediction_id=? ORDER BY created_at DESC LIMIT 100').all(req.user.uid,req.params.id).map(r=>({id:r.id,kind:r.kind,payload:JSON.parse(r.payload_json),hash:r.hash,createdAt:r.created_at,integrityOk:digest({uid:req.user.uid,pid:req.params.id,kind:r.kind,payload:JSON.parse(r.payload_json)})===r.hash}));res.json({records})});
