app.post('/api/v13/audit',requireAuth,(req,res)=>{const v=z.object({datasetId:z.string().uuid()}).safeParse(req.body);if(!v.success)return fail(res,400,'invalid dataset');const d=db.prepare('SELECT rows_json FROM learning_v10_datasets WHERE id=? AND user_id=?').get(v.data.datasetId,req.user.uid);if(!d)return fail(res,404,'dataset missing');try{const a=auditDataset(JSON.parse(d.rows_json));return res.json({ok:a.ok,sha256:a.sha256,counts:a.counts,issues:a.issues.slice(0,80)})}catch(e){return fail(res,422,e.message)}});
