app.post('/api/v13/tickets',requireAuth,(req,res)=>{const v=z.object({runId:z.string().uuid(),datasetId:z.string().uuid(),raceId:z.string().min(1).max(90),maxPoints:z.number().int().min(1).max(100).default(24),stake:z.number().int().min(100).max(10000).default(100)}).safeParse(req.body);if(!v.success)return fail(res,400,'invalid request');const run=db.prepare('SELECT * FROM learning_v10_runs WHERE id=? AND user_id=?').get(v.data.runId,req.user.uid);const d=db.prepare('SELECT * FROM learning_v10_datasets WHERE id=? AND user_id=?').get(v.data.datasetId,req.user.uid);if(!run||!d||run.dataset_id!==d.id)return fail(res,404,'run or dataset missing');try{const model=JSON.parse(run.report_json);const race=validateRows(JSON.parse(d.rows_json)).filter(x=>x.raceId===v.data.raceId&&x.region===model.region);if(race.length<3)return fail(res,422,'race needs 3 runners');const ranked=rankRace(race,model);return res.json({ranking:ranked,tickets:exactaTrifectaCandidates(ranked,v.data.maxPoints,v.data.stake),gate:releaseReadiness({model}),note:'研究用の参考順位と参考買い目。結果ラベルは推論には使用していませんが学習データ内のレースを評価する場合はアウトオブサンプルではありません。'})}catch(e){return fail(res,422,e.message)}});
